# Keep generated human prose readable without altering identifiers/paths in backticks.
import re
def readable(text):
 pieces=re.split(r'(`[^`]*`)',text)
 for i,x in enumerate(pieces):
  if x.startswith('`'):continue
  x=re.sub(r'\b(all|All|the|with|of|only|root|current|retains|covers|recomputes|preserves|plus|remain|remains|gives|earns|scope|sum|gross|net|into|and|decision|calculus|motion|visual|trig/log|classification|December|November|Grade|generation|versions)(?=\d)',r'\1 ',x)
  x=re.sub(r'(?<=\d)(?=(?:rows|parts|part|motion|single|derived|triples|candidate|files|analysis|review|paper|canonical|misread|edge|ordinary|historical|whole|examples|ledgers|rubric|fields|content|recipes|choices|marks|branch|Apply|Analyse|unconditional|conditional|text|graphs|unknown|facets|symmetric|retained|removed|added))',' ',x)
  for a,b in [('2020 syllabus','2020 syllabus'),('R4www','R4 www'),('b1/2','b 1/2'),('R1=0','R1=0'),('roots−3and4','roots −3 and 4'),('63/2m','63/2 m'),('velocities12and6','velocities 12 and 6'),('stepS3','step S3')]:x=x.replace(a,b)
  pieces[i]=x
 return ''.join(pieces)
